      ctx.fillStyle = b.color;
      ctx.fillRect(b.x - cam.x, b.y - cam.y, b.w, b.h);
      ctx.fillStyle = 'rgba(255,255,255,0.18)';
      for (let wx = b.x + 12; wx < b.x + b.w - 12; wx += 26) {
